import{_ as s,o as r,c as o,a2 as n}from"./chunks/framework.CqdVOxXJ.js";const e="/rakkii-cars-guide/screenshots/09-parts-inventory-canvass-restock-payables/01-parts-stock.png",a="/rakkii-cars-guide/screenshots/09-parts-inventory-canvass-restock-payables/02-payables.png",b=JSON.parse('{"title":"9. Parts & inventory, canvassing, restock POs & supplier payables","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/09-parts-inventory-canvass-restock-payables.md","filePath":"chapters/09-parts-inventory-canvass-restock-payables.md","lastUpdated":1793403538000}'),i={name:"chapters/09-parts-inventory-canvass-restock-payables.md"};function g(l,t,p,d,c,h){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_9-parts-inventory-canvassing-restock-pos-supplier-payables" tabindex="-1">9. Parts &amp; inventory, canvassing, restock POs &amp; supplier payables <a class="header-anchor" href="#_9-parts-inventory-canvassing-restock-pos-supplier-payables" aria-label="Permalink to &quot;9. Parts &amp; inventory, canvassing, restock POs &amp; supplier payables&quot;">​</a></h1><p><strong>For:</strong> Shop Owner (technicians with the canvass permission do the job-level steps) · <strong>Hubs:</strong> Workshop, Finance</p><p>Parts flow two ways at Rakkii:</p><ul><li><strong>Job parts</strong> bought for one car: canvassed and paid on the job (<strong>Canvass</strong> and <strong>Parts buy</strong> tabs).</li><li><strong>Shop stock</strong> kept on the shelf: tracked in <strong>Parts &amp; Inventory</strong>, refilled with <strong>restock POs</strong>.</li></ul><p>Every unpaid supplier bill from either route lands in <strong>Finance › Payables</strong>.</p><h2 id="_9-1-parts-catalog-stock-workshop-parts" tabindex="-1">9.1 Parts catalog &amp; stock (<code>/workshop/parts</code>) <a class="header-anchor" href="#_9-1-parts-catalog-stock-workshop-parts" aria-label="Permalink to &quot;9.1 Parts catalog &amp; stock (`/workshop/parts`)&quot;">​</a></h2><h3 id="add-a-part" tabindex="-1">Add a part <a class="header-anchor" href="#add-a-part" aria-label="Permalink to &quot;Add a part&quot;">​</a></h3><ol><li><strong>Workshop › Parts &amp; Inventory › Add part</strong>.</li><li>Fill <strong>Name</strong>, <strong>SKU</strong>, <strong>Unit</strong>, <strong>On hand</strong>, <strong>Reorder at</strong>, <strong>Last cost</strong>, <strong>Location</strong>, <strong>Preferred supplier</strong>, <strong>Category</strong>, and <strong>Status</strong> (Active / Inactive).</li><li>Press <strong>Add part</strong>.</li></ol><h3 id="the-stock-list" tabindex="-1">The stock list <a class="header-anchor" href="#the-stock-list" aria-label="Permalink to &quot;The stock list&quot;">​</a></h3><p>Columns: <strong>Name</strong> (with SKU and category under it), <strong>Location</strong>, <strong>On hand</strong> (with the unit, for example &quot;10 pc&quot;), <strong>Reorder at</strong>, <strong>Last cost</strong>, <strong>Value</strong>, <strong>Preferred supplier</strong>, and <strong>⋮</strong> for row actions. Inactive parts carry an <strong>Inactive</strong> badge by the name.</p><ul><li>On narrower screens (iPad, small laptops) <strong>Reorder at</strong>, <strong>Last cost</strong> and <strong>Preferred supplier</strong> step back so the table fits without scrolling sideways. They are still on each part&#39;s edit screen.</li><li>The tiles at the top read <strong>Parts</strong>, <strong>Low stock</strong>, <strong>Stock value</strong> and <strong>Pending requests</strong>.</li><li><strong>Search</strong>, <strong>Low stock</strong> and <strong>Category</strong> filters.</li><li>Select several rows to <strong>Set category</strong> in bulk.</li><li><strong>Low stock</strong> means on hand is at or below <strong>Reorder at</strong>, or below zero. Low parts are flagged here and when a technician picks the part on a job (&quot;on hand 2 · Low · min 4&quot;).</li></ul><h3 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Use it for</th></tr></thead><tbody><tr><td><strong>Edit</strong></td><td>Change details</td></tr><tr><td><strong>Receive</strong></td><td>Parts arrived without a PO: <strong>Quantity</strong> and optional <strong>Last cost</strong></td></tr><tr><td><strong>Adjust</strong></td><td>Stock count corrections: <strong>Quantity (signed)</strong> and <strong>Reason</strong>. Use a negative number to write off</td></tr><tr><td><strong>Stock moves</strong></td><td>History of every receive, adjustment and job use</td></tr></tbody></table><p>When a job line uses a <strong>Catalog part</strong>, stock is taken from on hand.</p><p><strong>Pending requests</strong> (from the page menu) lists job parts-buys waiting for payment or arrival, with <strong>Open job</strong>.</p><p><img src="'+e+'" alt="Parts &amp; Inventory stock list with Low stock filter"></p><h2 id="_9-2-reviewing-technician-canvass-quotes" tabindex="-1">9.2 Reviewing technician canvass quotes <a class="header-anchor" href="#_9-2-reviewing-technician-canvass-quotes" aria-label="Permalink to &quot;9.2 Reviewing technician canvass quotes&quot;">​</a></h2><p>When a job is marked <strong>Needs canvass</strong>, the technician (or desk) fills the <strong>Canvass</strong> tab (<a href="/rakkii-cars-guide/chapters/02-technician-daily-guide">Chapter 2</a>, section 2.7).</p><ol><li>Open the job&#39;s <strong>Canvass</strong> tab. The request status reads <strong>Draft</strong>, <strong>Sent</strong>, <strong>Quotes in</strong> or <strong>Approved</strong>.</li><li>Check each line&#39;s supplier quotes (<strong>A–D</strong> with price and lead days), the <strong>Chosen</strong> supplier and <strong>Line ₱</strong>.</li><li>Open the <strong>Quote files</strong> to verify the supplier quotations.</li><li>Compare <strong>Selected</strong> against <strong>Estimate parts</strong>. The budget is the <strong>cost</strong> of the approved estimate part lines — never the sell price. Over budget shows &quot;Selected cost exceeds estimate parts budget by ₱…&quot;.</li><li>Press <strong>Approve</strong>. Lines lock. Use <strong>Unlock</strong> if something has to change.</li></ol><p>While a canvass waits for approval, parts on that job cannot be marked arrived (&quot;Canvass pending — approval needed before parts can be marked arrived&quot;).</p><h2 id="_9-3-approving-parts-buy-on-jobs" tabindex="-1">9.3 Approving Parts buy on jobs <a class="header-anchor" href="#_9-3-approving-parts-buy-on-jobs" aria-label="Permalink to &quot;9.3 Approving Parts buy on jobs&quot;">​</a></h2><p>On the job&#39;s <strong>Parts buy</strong> tab each purchase shows <strong>Part</strong>, <strong>Supplier</strong>, <strong>Terms</strong>, <strong>Due date</strong>, <strong>Cost</strong>, <strong>Method</strong> and <strong>Status</strong> (<strong>To pay → Paid → Funds released → Arrived</strong>).</p><ol><li>Check the purchase and receipt photo.</li><li>If the shop setting <strong>Finance release before the car arrives</strong> is on, press <strong>Release funds</strong> (records who released and when).</li><li>When the part is in, <strong>Mark arrived</strong> with the official receipt attached.</li><li><strong>Print supplier request</strong> prints the Request for Payment.</li></ol><p>Who can pay suppliers: the owner, admin, and staff with <strong>Can canvass &amp; pay suppliers</strong>.</p><h2 id="_9-4-restock-pos-restock-pos-tab" tabindex="-1">9.4 Restock POs (Restock POs tab) <a class="header-anchor" href="#_9-4-restock-pos-restock-pos-tab" aria-label="Permalink to &quot;9.4 Restock POs (Restock POs tab)&quot;">​</a></h2><ol><li>Open <strong>Parts &amp; Inventory</strong>, page menu <strong>New PO</strong>.</li><li>Enter the supplier and a note. Add lines (<strong>Part</strong>, <strong>Qty</strong>, <strong>Unit cost</strong>) or press <strong>Start from low stock</strong> to fill every low part.</li><li>Set the <strong>Request for Payment</strong> terms (see 9.5).</li><li><strong>Create draft</strong>.</li><li>When sent to the supplier: <strong>Mark ordered</strong>.</li><li>When delivered: <strong>Mark received</strong>. Quantities are added to on hand and last cost is updated.</li></ol><p>The list filters <strong>All / Draft / Ordered / Received</strong> and shows <strong>Reference</strong>, <strong>Supplier</strong>, <strong>Terms</strong>, <strong>Due date</strong>, <strong>Status</strong>, <strong>Lines</strong>, <strong>Total</strong>, <strong>Updated</strong>. Drafts can be edited or deleted; <strong>View</strong> opens any PO with <strong>Payable</strong>, <strong>Paid</strong> and <strong>Balance</strong>.</p><h2 id="_9-5-supplier-payment-terms" tabindex="-1">9.5 Supplier payment terms <a class="header-anchor" href="#_9-5-supplier-payment-terms" aria-label="Permalink to &quot;9.5 Supplier payment terms&quot;">​</a></h2><p>Each parts buy and restock PO carries its own terms:</p><ul><li><strong>Terms</strong>: <strong>COD</strong>, <strong>Term</strong> (with <strong>Terms (days)</strong>), or <strong>From Rakkii stock</strong> (no supplier bill).</li><li><strong>Due date</strong> (from the term days), <strong>Supplier invoice ref</strong>, and <strong>Payable amount</strong> (blank uses the sum of line costs).</li><li><strong>Save terms</strong>.</li></ul><p>Shop defaults are in <strong>Admin › Shop settings › Buying</strong>: <strong>Default terms</strong> (COD to start), <strong>Default term days</strong> (30), <strong>Due-soon warning</strong> (3 days), <strong>Post supplier payments to expenses</strong> (on) and the <strong>Expense category</strong> used.</p><h2 id="_9-6-payables-finance-payables" tabindex="-1">9.6 Payables (<code>/finance/payables</code>) <a class="header-anchor" href="#_9-6-payables-finance-payables" aria-label="Permalink to &quot;9.6 Payables (`/finance/payables`)&quot;">​</a></h2><p>All supplier bills with a balance, from job parts-buys and restock POs. Parts taken from shop stock do not appear.</p><ul><li>Tabs: <strong>Due soon (n)</strong>, <strong>Overdue (n)</strong>, <strong>Open (n)</strong>, <strong>Paid (n)</strong>.</li><li><strong>Per supplier</strong> summary: bills, payable, paid, balance.</li><li><strong>Bills</strong>: <strong>Supplier</strong>, <strong>Source</strong> (job or PO), <strong>What</strong>, <strong>Terms</strong>, <strong>Due date</strong> (with due/overdue badges), <strong>Payable</strong>, <strong>Paid</strong>, <strong>Balance</strong>.</li><li>Totals: <strong>This tab</strong>, <strong>All unpaid bills</strong>, <strong>Due total</strong>. <strong>Export CSV</strong> and <strong>Print</strong>.</li></ul><h3 id="settle-a-supplier-bill" tabindex="-1">Settle a supplier bill <a class="header-anchor" href="#settle-a-supplier-bill" aria-label="Permalink to &quot;Settle a supplier bill&quot;">​</a></h3><ol><li>Press <strong>Record payment</strong> on the bill.</li><li>Choose the <strong>Kind</strong>: <strong>Initial payment</strong>, <strong>Partial payment</strong> or <strong>Final payment</strong>.</li><li>Enter <strong>Amount</strong>, <strong>Date</strong> and <strong>OR no.</strong> (official receipt number).</li><li>Leave <strong>Post to expenses</strong> on to log it as a shop expense (Parts category by default).</li><li><strong>Save</strong>. <strong>View payments</strong> shows the history; a wrong payment is <strong>Void</strong>ed with a reason.</li></ol><p>The <strong>Cash</strong> board shows how many payables are due soon or overdue.</p><p><img src="'+a+'" alt="Payables with Due soon / Overdue tabs and Record payment"></p>',38)])])}const m=s(i,[["render",g]]);export{b as __pageData,m as default};
